147	// free a local pointer  (page parameter comes first for better codegen)
148	static void mi_decl_noinline mi_free_generic_local(mi_page_t* page, void* p) mi_attr_noexcept {
149	  mi_assert_internal(p!=NULL && page != NULL);
150	  mi_block_t* const block = (mi_page_has_interior_pointers(page) ? _mi_page_ptr_unalign(page, p) : mi_validate_block_from_ptr(page,p));
151	  const bool was_guarded = mi_block_check_unguard(page, block, p);
152	  mi_free_block_local(page, block, was_guarded, true /* track stats */, true /* check for a full page */);
153	}
