427	// Helper for mi_free_try_collect_mt:  try to reclaim the page for ourselves
428	static mi_decl_noinline bool mi_abandoned_page_try_reclaim(mi_page_t* page, long reclaim_on_free) mi_attr_noexcept
429	{
430	  // note: reclaiming can improve benchmarks like `larson` or `rbtree-ck` a lot even in the single-threaded case,
431	  // since free-ing from an owned page avoids atomic operations. However, if we reclaim too eagerly in
432	  // a multi-threaded scenario we may start to hold on to too much memory and reduce reuse among threads.
433	  // If the current theap is where the page originally came from, we reclaim much more eagerly while
434	  // 'cross-thread' reclaiming on free is by default off (and we only 'reclaim' these by finding the abandoned
435	  // pages when we allocate a fresh page).
436	  mi_assert_internal(mi_page_is_owned(page));
437	  mi_assert_internal(mi_page_is_abandoned(page));
438	  mi_assert_internal(!mi_page_all_free(page));
439	  mi_assert_internal(page->block_size <= MI_MEDIUM_MAX_OBJ_SIZE);
440	  mi_assert_internal(reclaim_on_free >= 0);
441	  
442	  // dont reclaim if we just have terminated this thread and we should
443	  // not reinitialize the theap for this thread. (can happen due to thread-local destructors for example -- issue #944)
444	  if (!_mi_thread_is_initialized()) return false;
445	
446	  // get our theap 
447	  mi_theap_t* const theap = _mi_page_associated_theap_peek(page);
448	  if (theap==NULL || theap->tld==NULL || !theap->allow_page_reclaim) return false;  // see issue #1289
449	  
450	  // todo: cache `is_in_threadpool` and `exclusive_arena` directly in the theap for performance?
451	  // set max_reclaim limit
452	  long max_reclaim = 0;
453	  if mi_likely(theap == page->theap) {  // did this page originate from the current theap? (and thus allocated from this thread)
454	    // originating theap
455	    max_reclaim = _mi_option_get_fast(theap->tld->is_in_threadpool ? mi_option_page_cross_thread_max_reclaim : mi_option_page_max_reclaim);
456	  }
457	  else if (reclaim_on_free == 1 &&               // if cross-thread is allowed
458	            !theap->tld->is_in_threadpool &&      // and we are not part of a threadpool
459	            !mi_page_is_mostly_used(page) &&     // and the page is not too full
460	            _mi_arena_memid_is_suitable(page->memid, _mi_theap_heap(theap)->exclusive_arena)) {   // and it fits our memory
461	    // across threads
462	    max_reclaim = _mi_option_get_fast(mi_option_page_cross_thread_max_reclaim);
463	  }
464	
465	  // are we within the reclaim limit?
466	  if (max_reclaim >= 0 && !mi_page_queue_len_is_atmost(theap, page->block_size, max_reclaim)) {
467	    return false;
468	  }
469	
470	  // reclaim the page into this theap
471	  // first remove it from the abandoned pages in the arena -- this might wait for any readers to finish
472	  _mi_arenas_page_unabandon(page, theap);
473	  _mi_theap_page_reclaim(theap, page);
474	  mi_theap_stat_counter_increase(theap, pages_reclaim_on_free, 1);
475	  return true;
476	}
477	
478	
479	// We freed a block in an abandoned page (that was not owned). Try to collect
480	static void mi_decl_noinline mi_free_try_collect_mt(mi_page_t* page, mi_block_t* mt_free) mi_attr_noexcept
481	{
482	  mi_assert_internal(mi_page_is_owned(page));
483	  mi_assert_internal(mi_page_is_abandoned(page));
484	  mi_assert_internal(mt_free != NULL);
485	  // mi_assert_internal(_mi_subproc() == mi_page_subproc(page));  // never collect across subprocesses
486	  
487	  // we own the page now, and it is safe to collect the thread atomic free list
488	  if (page->block_size <= MI_SMALL_SIZE_MAX) {
489	    // use the `_partly` version to avoid atomic operations since we already have the `mt_free` pointing into the thread free list
490	    // (after this the `used` count might be too high (as some blocks may have been concurrently added to the thread free list and are yet uncounted).
491	    //  however, if the page became completely free, the used count is guaranteed to be 0.)
492	    mi_assert_internal(page->reserved>=16); // below this even one freed block goes from full to no longer mostly used.
493	    _mi_page_free_collect_partly(page, mt_free);    
494	  }
495	  else {
496	    // for larger blocks we use the regular collect 
497	    _mi_page_free_collect(page,false /* no force */);
498	    mt_free = NULL; // expected page->xthread_free value after collection
499	  }
500	  const long reclaim_on_free = _mi_option_get_fast(mi_option_page_reclaim_on_free);
501	  #if MI_DEBUG > 1
502	  if (mi_page_is_singleton(page)) { mi_assert_internal(mi_page_all_free(page)); }
503	  if (mi_page_is_full(page))      { mi_assert(mi_page_is_mostly_used(page)); }
504	  #endif
505	
506	  // try to: 1. free it, 2. reclaim it, or 3. reabandon it to be mapped
507	  if (mi_abandoned_page_try_free(page)) return;
508	  if (page->block_size <= MI_MEDIUM_MAX_OBJ_SIZE && reclaim_on_free >= 0) {  // early test for better codegen
509	    if (mi_abandoned_page_try_reclaim(page, reclaim_on_free)) return;
510	  }
511	  if (mi_abandoned_page_try_reabandon_to_mapped(page)) return;
512	  
513	  // otherwise unown the page again
514	  mi_abandoned_page_unown_from_free(page, mt_free);
515	}
516	
517	
518	// ------------------------------------------------------
519	// Usable size 
520	// ------------------------------------------------------
521	
522	// Bytes available in a block
523	static size_t mi_decl_noinline mi_page_usable_aligned_size_of(const mi_page_t* page, const void* p) mi_attr_noexcept {
524	  const mi_block_t* block = _mi_page_ptr_unalign(page, p);
525	  const bool is_guarded = mi_block_ptr_is_guarded(block,p);
526	  const size_t size = mi_page_usable_size_of(page, block, is_guarded);
527	  mi_assert_internal((void*)p >= (void*)block);
528	  const size_t adjust = (uint8_t*)p - (uint8_t*)block;
529	  mi_assert_internal(adjust <= size);
530	  const size_t aligned_size = (adjust <= size ? size - adjust : 0);  // size can be zero if the padding is corrupted
531	  return aligned_size;
532	}
533	
534	size_t _mi_page_usable_size(const mi_page_t* page, const void* p) mi_attr_noexcept {
535	  if mi_unlikely(page==NULL) return 0;
536	  mi_assert_internal(mi_validate_ptr_page(p,"_mi_page_usable_size") == page);
537	  if mi_likely(!mi_page_has_interior_pointers(page)) {
538	    const mi_block_t* block = mi_validate_block_from_ptr(page,p);
539	    return mi_page_usable_size_of(page, block, false /* is guarded */);
540	  }
541	  else {
542	    // split out to separate routine for improved code generation
543	    return mi_page_usable_aligned_size_of(page, p);
544	  }
545	}
546	
547	mi_decl_nodiscard size_t mi_usable_size(const void* p) mi_attr_noexcept {
548	  const mi_page_t* const page = mi_validate_ptr_page(p,"mi_usable_size");
549	  return _mi_page_usable_size(page,p);
550	}
551	
552	
553	// ------------------------------------------------------
554	// Deprecated: double free is checked with padding now.
555	// Check for double free in secure and debug mode
556	// This is somewhat expensive so only enabled for secure mode 4
557	// ------------------------------------------------------
558	
559	#if MI_CHECK_DOUBLE_FREE      
560	// linear check if the free list contains a specific element
561	static bool mi_list_contains(const mi_page_t* page, const mi_block_t* list, const mi_block_t* elem, const char* list_kind) {
562	  const size_t max_count = page->capacity;      // can never hold more blocks than the capacity
563	  size_t count = 0;
564	  while (list != NULL && count <= max_count) {  // double-free can create cycles so we limit the number of iterations
565	    if (elem==list) return true;
566	    list = mi_block_next(page, list);
567	    count++;    
568	  }
569	  if mi_unlikely(count > max_count) {
570	    _mi_error_message(EFAULT, "corrupted %s list (possibly due to a double free)\n", list_kind);
571	  }
572	  return false;
573	}
574	
575	static mi_decl_noinline bool mi_check_is_double_freex(const mi_page_t* page, const mi_block_t* block) {
576	  // The decoded value is in the same page (or NULL).
577	  // Walk the free lists to verify positively if it is already freed
578	  if (mi_list_contains(page, page->free, block, "free") ||
579	      mi_list_contains(page, page->local_free, block, "local free") ||
580	      mi_list_contains(page, mi_page_thread_free(page), block, "thread free"))
581	  {
582	    _mi_error_message(EAGAIN, "double free detected of block %p with size %zu\n", block, mi_page_block_size(page));
583	    return true;
584	  }
585	  return false;
586	}
587	
588	// Used for double free checking to avoid checking free lists too frequently
589	static inline bool mi_block_could_be_double_free(const mi_page_t* page, const mi_block_t* block) {
590	  mi_block_t* n = mi_block_nextx(page,block,page->keys);
591	  return (((uintptr_t)n & (MI_INTPTR_SIZE-1))==0 &&       // quick check: aligned pointer?
592	          (n==NULL || mi_page_contains_address(page,n))); // quick check: in the same page or NULL?  
593	}
594	
595	// check if `block` was free'd before
596	static inline bool mi_check_is_double_free(const mi_page_t* page, const mi_block_t* block) {
597	  if mi_unlikely(mi_block_could_be_double_free(page,block))  // quick check: next field is aligned in the same page or NULL?
598	  {
599	    // Suspicious: decoded value a in block is in the same page (or NULL) -- maybe a double free?
600	    // (continue in separate function to improve code generation)
601	    return mi_check_is_double_freex(page, block);
602	  }
603	  else return false;
604	}
605	#else
606	static inline bool mi_check_is_double_free(const mi_page_t* page, const mi_block_t* block) {
607	  MI_UNUSED(page);
608	  MI_UNUSED(block);
609	  return false;
610	}
611	#endif
612	
613	
614	// ---------------------------------------------------------------------------
615	// Check for theap block overflow by setting up padding at the end of the block
616	// ---------------------------------------------------------------------------
617	
618	#if MI_PADDING // && !MI_TRACK_ENABLED
619	static inline bool mi_page_decode_padding(const mi_page_t* page, const mi_block_t* block, size_t* delta, size_t* bsize, bool* double_free) {
620	  *bsize = mi_page_usable_block_size(page);
621	  mi_padding_t* const padding = (mi_padding_t*)((uint8_t*)block + *bsize);
622	  mi_track_mem_defined(padding,sizeof(mi_padding_t));
623	  *delta = padding->delta;
624	  const uint32_t canary = padding->canary;
625	  const bool ok = (mi_ptr_encode_canary(page,block,page->keys) == canary && *delta <= *bsize);
626	  if (double_free!=NULL) {
627	    if mi_unlikely(!ok) { *double_free = mi_ptr_decode_canary_is_freed(canary); }   // double free?
628	                   else { padding->canary = mi_ptr_encode_canary_freed(); }         // mark as freed
629	  }
630	  mi_track_mem_noaccess(padding,sizeof(mi_padding_t));
631	  return ok;
632	}
633	
634	// Return the exact usable size of a block.
635	static size_t mi_page_usable_size_of(const mi_page_t* page, const mi_block_t* block, bool is_guarded) {
636	  if mi_unlikely(is_guarded) {
637	    const size_t bsize = mi_page_block_size(page);
638	    return (bsize - _mi_os_page_size());
639	  }
640	  else {
641	    size_t bsize;
642	    size_t delta;
643	    bool ok = mi_page_decode_padding(page, block, &delta, &bsize, NULL);
644	    mi_assert_internal(ok); mi_assert_internal(delta <= bsize);
645	    return (ok ? bsize - delta : 0);
646	  }
647	}
648	
649	// When a non-thread-local block is freed, it becomes part of the thread delayed free
650	// list that is freed later by the owning theap. If the exact usable size is too small to
651	// contain the pointer for the delayed list, then shrink the padding (by decreasing delta)
652	// so it will later not trigger an overflow error in `mi_free_block`.
653	void _mi_padding_shrink(const mi_page_t* page, const mi_block_t* block, const size_t min_size) {
654	  size_t bsize;
655	  size_t delta;
656	  bool ok = mi_page_decode_padding(page, block, &delta, &bsize, NULL);
657	  mi_assert_internal(ok);
658	  if (!ok || (bsize - delta) >= min_size) return;  // usually already enough space
659	  mi_assert_internal(bsize >= min_size);
660	  if (bsize < min_size) return;  // should never happen
661	  size_t new_delta = (bsize - min_size);
662	  mi_assert_internal(new_delta < bsize);
663	  mi_padding_t* padding = (mi_padding_t*)((uint8_t*)block + bsize);
664	  mi_track_mem_defined(padding,sizeof(mi_padding_t));
665	  padding->delta = (uint32_t)new_delta;
666	  mi_track_mem_noaccess(padding,sizeof(mi_padding_t));
667	}
668	#else
669	static inline size_t mi_page_usable_size_of(const mi_page_t* page, const mi_block_t* block, bool is_guarded) {
670	  MI_UNUSED(block);
671	  if mi_unlikely(is_guarded) {
672	    const size_t bsize = mi_page_block_size(page);
673	    return (bsize - _mi_os_page_size());
674	  }
675	  else {
676	    return mi_page_usable_block_size(page);
677	  }
678	}
679	
680	void _mi_padding_shrink(const mi_page_t* page, const mi_block_t* block, const size_t min_size) {
681	  MI_UNUSED(page); MI_UNUSED(block); MI_UNUSED(min_size);
682	}
683	#endif
684	
685	#if MI_PADDING
686	
687	static bool mi_verify_padding(const mi_page_t* page, const mi_block_t* block, size_t* size, size_t* wrong, bool* is_double_free) {
688	  size_t bsize;
689	  size_t delta;
690	  bool ok = mi_page_decode_padding(page, block, &delta, &bsize, is_double_free );
691	  *size = *wrong = bsize;
692	  if (!ok) return false;
693	  mi_assert_internal(bsize >= delta);
694	  *size = bsize - delta;
695	  #if MI_PADDING_CHECK_BYTES
696	  if (!mi_page_is_huge(page)) {
697	    uint8_t* fill = (uint8_t*)block + bsize - delta;
698	    const size_t maxpad = (delta > MI_MAX_ALIGN_SIZE ? MI_MAX_ALIGN_SIZE : delta); // check at most the first N padding bytes
699	    mi_track_mem_defined(fill, maxpad);
700	    for (size_t i = 0; i < maxpad; i++) {
701	      if (fill[i] != MI_DEBUG_PADDING) {
702	        *wrong = bsize - delta + i;
703	        ok = false;
704	        break;
705	      }
706	    }
707	    mi_track_mem_noaccess(fill, maxpad);
708	  }
709	  #endif
710	  return ok;
711	}
712	
713	mi_decl_nodiscard static bool mi_check_padding_on_free(const mi_page_t* page, const mi_block_t* block, bool is_guarded, size_t* usable_size) {
714	  if mi_unlikely(is_guarded) {
715	    const size_t bsize = mi_page_block_size(page);
716	    *usable_size = (bsize - _mi_os_page_size());
717	    return true;
718	  }
719	  else {
720	    size_t wrong;
721	    bool is_double_free;
722	    if mi_unlikely(!mi_verify_padding(page,block,usable_size,&wrong,&is_double_free)) {
723	      if (is_double_free) {
724	        _mi_error_message(EAGAIN, "double free detected of heap block %p with size %zu\n", block, *usable_size);
725	      }
726	      else {
727	        _mi_error_message(EFAULT, "buffer overflow in heap block %p of size %zu: write after %zu bytes\n", block, *usable_size, wrong );
728	      }
729	      return false;  
730	    }
731	    return true;
732	  }
733	}
734	
735	#else
736	
737	mi_decl_nodiscard static bool mi_check_padding_on_free(const mi_page_t* page, const mi_block_t* block, bool is_guarded, size_t* usable_size) {
738	  *usable_size = mi_page_usable_size_of(page,block,is_guarded);
739	  return true;
740	}
741	
742	#endif
743	
744	// only maintain stats for smaller objects if requested
745	#if (MI_STAT>0)
746	static void mi_stat_free(const mi_page_t* page, const mi_block_t* block) {
747	  MI_UNUSED(block);  
748	  mi_theap_t* theap = _mi_theap_default();
749	  mi_lock_t* lock = NULL;
750	  mi_subproc_t* const subproc = mi_page_subproc(page);
751	  mi_theap_t* const theap_meta = subproc->theap_meta;
752	  if mi_unlikely(!mi_theap_is_initialized(theap) || // can happen if free'd after thread_done was called (usually a thread cleanup call by the OS)
753	                  // page->theap == subproc->theap_meta  .. but we cannot read `theap` if we don't own the page
754	                  (theap_meta != NULL && mi_page_thread_id(page) == theap_meta->tld->thread_id)) { 
755	    theap = theap_meta;
756	    lock = &subproc->theap_meta_lock;
757	    mi_lock_acquire(lock);
758	  }
759	
760	  const size_t bsize = mi_page_usable_block_size(page);
761	  // #if (MI_STAT>1)
762	  // const size_t usize = mi_page_usable_size_of(page, block);
763	  // mi_theap_stat_decrease(theap, malloc_requested, usize);
764	  // #endif
765	  if (bsize <= MI_LARGE_MAX_OBJ_SIZE) {
766	    mi_theap_stat_decrease(theap, malloc_normal, bsize);
767	    #if (MI_STAT > 1)
768	    mi_theap_stat_decrease(theap, malloc_bins[_mi_bin(bsize)], 1);
769	    #endif
770	  }
771	  else {
772	    const size_t bpsize = mi_page_block_size(page);  // match stat in page.c:mi_huge_page_alloc
773	    mi_theap_stat_decrease(theap, malloc_huge, bpsize);
774	  }
775	
776	  if mi_unlikely(lock!=NULL) {
777	    mi_lock_release(lock);
778	  }
779	}
780	#else
781	void mi_stat_free(const mi_page_t* page, const mi_block_t* block) {
782	  MI_UNUSED(page); MI_UNUSED(block);
783	}
784	#endif
785	
786	
787	// Remove guard page when building with MI_GUARDED
788	#if MI_GUARDED
789	static void mi_block_unguard(mi_page_t* page, mi_block_t* block, void* p) {
790	  MI_UNUSED(p);
791	  mi_assert_internal(mi_block_ptr_is_guarded(block, p));
792	  mi_assert_internal(mi_page_has_interior_pointers(page));
793	  mi_assert_internal((uint8_t*)p - (uint8_t*)block >= (ptrdiff_t)sizeof(mi_block_t));
794	  mi_assert_internal(block->next == MI_BLOCK_TAG_GUARDED);
795	
796	  const size_t bsize = mi_page_block_size(page);
797	  const size_t psize = _mi_os_page_size();
798	  mi_assert_internal(bsize > psize);
799	  mi_assert_internal(!page->memid.is_pinned);
800	  void* gpage = (uint8_t*)block + bsize - psize;
801	  mi_assert_internal(_mi_is_aligned(gpage, psize));
802	  _mi_os_unprotect(gpage, psize);
803	}
804	
805	// unguard a whole page (called from `mi_heap_destroy`)
806	void _mi_page_unguard_all(mi_page_t* page) {      
807	  if mi_likely(!mi_page_has_interior_pointers(page)) return;
808	  uint8_t* const start = mi_page_start(page);
809	  const size_t psize = mi_page_committed(page);
810	  _mi_os_unprotect(start,psize);  // unprotect all at once as we cannot know which blocks are guarded
811	}
812	#else
813	void _mi_page_unguard_all(mi_page_t* page) {
814	  MI_UNUSED(page);
815	  // nothing to do 
816	}
817	#endif
