130	mi_decl_nodiscard static bool mi_arena_commit(mi_subproc_t* subproc, mi_arena_t* arena, void* start, size_t size, bool* is_zero, size_t stat_already_committed) {
131	  mi_assert_internal(subproc!=NULL);
132	  if (arena != NULL && arena->commit_fun != NULL) {
133	    return (*arena->commit_fun)(true, start, size, is_zero, arena->commit_fun_arg);
134	  }
135	  else if (stat_already_committed > 0) {
136	    return _mi_os_commit_ex(subproc, start, size, is_zero, stat_already_committed);
137	  }
138	  else {
139	    return _mi_os_commit(subproc, start, size, is_zero);
140	  }
141	}
