222	  if (page->memid.memkind == MI_MEM_ARENA) {
223	    return page->memid.mem.arena.slice_count * MI_ARENA_SLICE_SIZE;
224	  }
225	  else if (mi_memid_is_os(page->memid) || page->memid.memkind == MI_MEM_EXTERNAL) {
226	    mi_assert_internal((uint8_t*)page->memid.mem.os.base <= (uint8_t*)page);
227	    const ptrdiff_t presize = (uint8_t*)page - (uint8_t*)page->memid.mem.os.base;
228	    mi_assert_internal((ptrdiff_t)page->memid.mem.os.size >= presize);
229	    return (presize > (ptrdiff_t)page->memid.mem.os.size ? 0 : page->memid.mem.os.size - presize);
230	  }
231	  else {
232	    return 0;
233	  }
