236	/* -----------------------------------------------------------
237	  Arena Allocation
238	----------------------------------------------------------- */
239	
240	static mi_decl_noinline void* mi_arena_try_alloc_at(
241	  mi_arena_t* arena, size_t slice_count, bool commit, size_t tseq, mi_memid_t* memid)
242	{
243	  mi_assert_internal(arena!=NULL);
244	  mi_assert_internal(slice_count>0);
245	  size_t slice_index;
246	  if (!mi_bbitmap_try_find_and_clearN(arena->slices_free, tseq, slice_count, &slice_index)) return NULL;
247	
248	  // claimed it!
249	  void* p = mi_arena_slice_start(arena, slice_index);
250	  *memid = mi_memid_create_arena(arena, slice_index, slice_count);
251	  memid->is_pinned = arena->memid.is_pinned;
252	
253	  // set the dirty bits and track which slices become accessible
254	  size_t touched_slices = slice_count;
255	  if (arena->memid.initially_zero) {
256	    size_t already_dirty = 0;
257	    memid->initially_zero = mi_bitmap_setN(arena->slices_dirty, slice_index, slice_count, &already_dirty);
258	    mi_assert_internal(already_dirty <= touched_slices);
259	    touched_slices -= already_dirty;
260	  }
261	  else {
262	    // todo: properly count touched pages with a separate bitmap?
263	    touched_slices = 0; 
264	  }
265	
266	  // set commit state
267	  if (commit) {
268	    // commit requested, but the range may not be committed as a whole: ensure it is committed now
269	    const size_t already_committed = mi_bitmap_popcountN(arena->slices_committed, slice_index, slice_count);
270	    if (already_committed < slice_count) {
271	      // not all committed, try to commit now
272	      bool commit_zero = false;
273	      if (!mi_arena_commit(arena->subproc, arena, p, mi_size_of_slices(slice_count), &commit_zero, mi_size_of_slices(already_committed))) {
274	        // if the commit fails, release ownership, and return NULL;
275	        // note: this does not roll back dirty bits but that is ok.
276	        mi_bbitmap_setN(arena->slices_free, slice_index, slice_count);
277	        return NULL;
278	      }
279	      if (commit_zero) {
280	        memid->initially_zero = true;
281	      }
282	
283	      // set the commit bits
284	      mi_bitmap_setN(arena->slices_committed, slice_index, slice_count, NULL);
285	
286	      // committed
287	      #if MI_DEBUG > 1
288	      if (memid->initially_zero) {
289	        if (!mi_mem_is_zero(p, mi_size_of_slices(slice_count))) {
290	          _mi_error_message(EFAULT, "internal error: arena allocation was not zero-initialized!\n");
291	          memid->initially_zero = false;
292	        }
293	      }
294	      #endif
295	    }
296	    else {
297	      // already fully committed.
298	      _mi_os_reuse(arena->subproc, p, mi_size_of_slices(slice_count));
299	      // if the OS has overcommit, and this is the first time we access these pages, then
300	      // count the commit now (as at arena reserve we didn't count those commits as these are on-demand)
301	      if (_mi_os_has_overcommit() && touched_slices > 0 && !arena->memid.is_pinned /* huge pages, issue #1236 */) {
302	        mi_subproc_stat_increase( arena->subproc, committed, mi_size_of_slices(touched_slices));
303	      }
304	    }
305	
306	    mi_assert_internal(mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
307	    memid->initially_committed = true;
308	
309	    // tool support
310	    if (memid->initially_zero) {
311	      mi_track_mem_defined(p, slice_count * MI_ARENA_SLICE_SIZE);
312	    }
313	    else {
314	      mi_track_mem_undefined(p, slice_count * MI_ARENA_SLICE_SIZE);
315	    }
316	  }
317	  else {
318	    // no need to commit, but check if it is already fully committed
319	    memid->initially_committed = mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count);
320	    if (!memid->initially_committed) {
321	      // partly committed.. adjust stats
322	      size_t already_committed_count = 0;
323	      mi_bitmap_setN(arena->slices_committed, slice_index, slice_count, &already_committed_count);
324	      mi_bitmap_clearN(arena->slices_committed, slice_index, slice_count);
325	      mi_subproc_stat_decrease(arena->subproc, committed, mi_size_of_slices(already_committed_count));
326	    }
327	  }
328	
329	  mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
330	  if (commit) { mi_assert_internal(mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count)); }
331	  if (commit) { mi_assert_internal(memid->initially_committed); }
332	  mi_assert_internal(mi_bitmap_is_setN(arena->slices_dirty, slice_index, slice_count));
333	
334	  return p;
335	}
