524	// Allocate slices from the arena's -- potentially allocating a fresh arena
525	static mi_decl_noinline void* mi_arenas_try_alloc(
526	  mi_heap_t* heap,
527	  size_t slice_count, size_t alignment,
528	  bool commit, bool allow_large,
529	  mi_arena_t* req_arena, size_t tseq, int numa_node, mi_memid_t* memid)
530	{
531	  // mi_assert(slice_count <= MI_ARENA_MAX_CHUNK_OBJ_SLICES);
532	  mi_assert(alignment <= MI_ARENA_SLICE_ALIGN);
533	  void* p;
534	
535	  // not too large?
536	  if (slice_count * MI_ARENA_SLICE_SIZE > MI_ARENA_MAX_SIZE) return NULL;
537	
538	  // try to find free slices in the arena's
539	  p = mi_arenas_try_find_free(heap, slice_count, alignment, commit, allow_large, req_arena, tseq, numa_node, memid);
540	  if (p != NULL) return p;
541	
542	  // did we need a specific arena?
543	  if (req_arena != NULL) return NULL;
544	
545	  // don't create arena's while preloading (todo: or should we?)
546	  // if (_mi_preloading()) return NULL;
547	
548	  // don't create arena's if OS allocation is disallowed
549	  if (mi_option_is_enabled(mi_option_disallow_os_alloc)) return NULL;
550	
551	  // otherwise, try to reserve a new arena -- but one thread at a time.. (todo: allow 2 or 4 to reduce contention?)
552	  mi_subproc_t* const subproc = heap->subproc;
553	  const size_t arena_count = mi_arenas_get_count(subproc);
554	  mi_lock(&subproc->arena_reserve_lock) {
555	    if (arena_count == mi_arenas_get_count(subproc)) {
556	      // we are the first to enter the lock, reserve a fresh arena
557	      mi_arena_id_t arena_id = _mi_arena_id_none();
558	      mi_arena_reserve(subproc, mi_size_of_slices(slice_count), allow_large, &arena_id);
559	    }
560	    else {
561	      // another thread already reserved a new arena
562	    }
563	  }
564	  // try once more to allocate in the new arena
565	  mi_assert_internal(req_arena == NULL);
566	  p = mi_arenas_try_find_free(heap, slice_count, alignment, commit, allow_large, req_arena, tseq, numa_node, memid);
567	  if (p != NULL) return p;
568	
569	  return NULL;
570	}
