594	// Allocate large sized memory
595	void* _mi_arenas_alloc_aligned( mi_heap_t* heap,
596	  size_t size, size_t alignment, size_t align_offset,
597	  bool commit, bool allow_large,
598	  mi_arena_t* req_arena, size_t tseq, int numa_node, mi_memid_t* memid)
599	{
600	  mi_assert_internal(memid != NULL);
601	  mi_assert_internal(size > 0);
602	
603	  // try to allocate in an arena if the alignment is small enough and the object is not too small (as for theap meta data)
604	  if (!mi_option_is_enabled(mi_option_disallow_arena_alloc) &&                // is arena allocation allowed?
605	      size >= MI_ARENA_MIN_OBJ_SIZE && size <= mi_arena_max_object_size() &&  // and not too small or too large
606	      alignment <= MI_ARENA_SLICE_ALIGN && align_offset == 0)                 // and good alignment
607	  {
608	    const size_t slice_count = mi_slice_count_of_size(size);
609	    void* p = mi_arenas_try_alloc(heap, slice_count, alignment, commit, allow_large, req_arena, tseq, numa_node, memid);
610	    if (p != NULL) return p;
611	  }
612	
613	  // fall back to the OS
614	  void* p = mi_arena_os_alloc_aligned(heap->subproc, size, alignment, align_offset, commit, allow_large, req_arena, memid);
615	  return p;
616	}
