654	
655	static bool mi_arena_try_claim_abandoned(size_t slice_index, mi_arena_t* arena, bool* keep_abandoned) {
656	  // found an abandoned page of the right size
657	  mi_page_t* const page  = mi_arena_page_at_slice(arena, slice_index);
658	  // can we claim ownership?
659	  if (!mi_page_claim_ownership(page)) {
660	    // there was a concurrent free that reclaims this page ..
661	    // we need to keep it in the abandoned map as the free will call `mi_arena_page_unabandon`,
662	    // and wait for readers (us!) to finish. This is why it is very important to set the abandoned
663	    // bit again (or otherwise the unabandon will never stop waiting).
664	    *keep_abandoned = true;
665	    return false;
666	  }
667	  else {
668	    // yes, we can reclaim it, keep the abandoned map entry clear
669	    *keep_abandoned = false;
670	    return true;
671	  }
672	}
