874	#if !MI_PAGE_META_IS_ALIGNED
875	// Only used for non-separate pages
876	static size_t mi_page_block_start(size_t block_size, bool os_align)
877	{
878	  size_t offset;  
879	  #if MI_GUARDED
880	  // in a guarded build, we align pages with blocks a multiple of an OS page size, to the OS page size
881	  // this ensures that all blocks in such pages are OS page size aligned (which is needed for the guard pages)
882	  const size_t os_page_size = _mi_os_page_size();
883	  mi_assert_internal(MI_PAGE_ALIGN >= os_page_size);
884	  if (!os_align && block_size % os_page_size == 0 && block_size > os_page_size /* at least 2 or more */ ) {
885	    offset = _mi_align_up(mi_page_info_size(), os_page_size);
886	  }
887	  else
888	  #endif
889	  if (os_align) {
890	    offset = MI_PAGE_ALIGN;
891	  }
892	  else if (_mi_is_power_of_two(block_size) && block_size <= MI_PAGE_MAX_START_BLOCK_ALIGN2) {
893	    // naturally align power-of-2 blocks up to MI_PAGE_MAX_START_BLOCK_ALIGN2 size (4KiB)
894	    offset = _mi_align_up(mi_page_info_size(), block_size);
895	  }
896	  else if (block_size != 0 && (block_size % MI_PAGE_OSPAGE_BLOCK_ALIGN2) == 0) {
897	    // also align large pages that are a multiple of MI_PAGE_OSPAGE_BLOCK_ALIGN2 (4KiB)
898	    offset = _mi_align_up(mi_page_info_size(), MI_PAGE_OSPAGE_BLOCK_ALIGN2);
899	  }
900	  else {
901	    // otherwise start after the info
902	    offset = mi_page_info_size();
903	  }
904	  return _mi_align_up(offset,MI_MAX_ALIGN_SIZE);
905	}
906	#endif
