950	// Allocate a fresh page
951	static mi_page_t* mi_arenas_page_alloc_fresh(mi_theap_t* theap, size_t slice_count, size_t block_size, size_t block_alignment, bool commit)
952	{
953	  const bool os_align           = (block_alignment > MI_PAGE_MAX_OVERALLOC_ALIGN);
954	  const bool singleton          = (os_align || block_size > MI_LARGE_MAX_OBJ_SIZE);
955	  const size_t max_page_meta_count = (singleton && slice_count > 2 ? 2 : slice_count); 
956	      
957	  const size_t alloc_size       = mi_size_of_slices(slice_count);
958	  mi_memid_t memid              = _mi_memid_none();
959	  mi_arena_pages_t* arena_pages = NULL;
960	  uint8_t* const slice_start    = mi_arenas_page_alloc_fresh_area(theap,slice_count,max_page_meta_count,block_alignment,os_align,commit,&memid,&arena_pages);
961	  if (!slice_start) return NULL;
962	
963	  // guard page at the end of mimalloc page?
964	  #if MI_SECURE>=5
965	  mi_assert(alloc_size > _mi_os_secure_guard_page_size());
966	  const size_t page_noguard_size = alloc_size - _mi_os_secure_guard_page_size();
967	  #else
968	  const size_t page_noguard_size = alloc_size;
969	  #endif
970	
971	  // allocate the page meta info
972	  mi_page_t* page = NULL;
973	  bool page_meta_is_separate = false;
974	  size_t block_start = 0;
975	
976	  // allocate page meta info at the arena start?
977	  mi_page_t* const page_meta = mi_arena_page_meta(memid,slice_start);
978	  if (page_meta!=NULL) {
979	    mi_assert_internal(page_meta->block_size == 0);
980	    #if MI_PAGE_META_SMALL_IS_ALIGNED
981	    // if `block_size <= MI_SMALL_SIZE_MAX` we put the page info in front of the slice,
982	    // (note: it is important that `page_meta->block_size == 0` for `mi_arena_page_at_slice`)
983	    if (block_size > MI_SMALL_SIZE_MAX)
984	    #endif
985	    {
986	      page = page_meta;
987	      page_meta_is_separate = true;
988	      block_start = 0;
989	      #if !defined(MI_PAGE_BLOCK_START_MAX_OFFSET)
990	      #define MI_PAGE_BLOCK_START_MAX_OFFSET  (8*MI_INTPTR_BITS) /* 512 */
991	      #endif
992	      if (block_size >= MI_INTPTR_SIZE && block_size <= MI_PAGE_BLOCK_START_MAX_OFFSET && _mi_is_power_of_two(block_size)) {
993	        block_start += block_size;
994	      }
995	      mi_assert_internal(page->block_size == 0);
996	      _mi_memzero_aligned(page, sizeof(*page));
997	    }
998	  }
999	  if (page == NULL) {
1000	    #if MI_PAGE_META_IS_ALIGNED
1001	    // can only happen on failing to commit the page meta info
1002	    _mi_arenas_free(_mi_theap_subproc(theap),slice_start,alloc_size,memid);
1003	    return NULL;
1004	    #else
1005	    // put page meta info in front of the slice
1006	    page = (mi_page_t*)slice_start;
1007	    block_start = mi_page_block_start(block_size, os_align);
1008	    #endif
1009	  }
1010	  mi_assert_internal(block_start % MI_MAX_ALIGN_SIZE == 0);
1011	
1012	  // commit first block?
1013	  size_t commit_size = 0;
1014	  if (!memid.initially_committed) {
1015	    commit_size = _mi_align_up(block_start + block_size, mi_page_min_commit_size());
1016	    if (commit_size > page_noguard_size) { commit_size = page_noguard_size; }
1017	    bool is_zero = false;
1018	    if mi_unlikely(!mi_arena_commit( _mi_theap_subproc(theap), mi_memid_arena(memid), slice_start, commit_size, &is_zero, 0)) {
1019	      _mi_arenas_free(_mi_theap_subproc(theap), slice_start, alloc_size, memid);
1020	      return NULL;
1021	    }
1022	  }
1023	  // now we can finish initalization and use `mi_arenas_free_page_prim` on error
1024	  
1025	  // zero initialize the page meta data
1026	  if (!memid.initially_zero && !page_meta_is_separate) {
1027	    _mi_memzero_aligned(page, sizeof(*page));
1028	  }
1029	
1030	  // set the guard page
1031	  #if MI_SECURE>=5
1032	  if (memid.initially_committed) {
1033	    _mi_os_secure_guard_page_set_at(_mi_theap_subproc(theap), slice_start + page_noguard_size, memid);
1034	  }
1035	  #endif
1036	  
1037	  // claimed free slices: initialize the page partly
1038	  if (!memid.initially_zero && memid.initially_committed) {
1039	    mi_track_mem_undefined(slice_start, slice_count * MI_ARENA_SLICE_SIZE);
1040	  }
1041	  else if (memid.initially_committed) {
1042	    mi_track_mem_defined(slice_start, slice_count * MI_ARENA_SLICE_SIZE);
1043	  }
1044	  #if MI_DEBUG > 1
1045	  if (memid.initially_zero && memid.initially_committed) {
1046	    if (!mi_mem_is_zero(slice_start, page_noguard_size)) {
1047	      _mi_error_message(EFAULT, "internal error: page memory was not zero initialized.\n");
1048	      memid.initially_zero = false;
1049	      if (block_start > 0) { _mi_memzero_aligned(page, sizeof(*page)); }
1050	    }
1051	  }
1052	  #endif
1053	  const size_t reserved = (os_align ? 1 : (page_noguard_size - block_start) / block_size);
1054	  mi_assert_internal(reserved > 0 && reserved <= UINT16_MAX);
1055	
1056	  // initialize the page start
1057	  uint8_t* const start = slice_start + block_start;
1058	  mi_assert_internal(start > (uint8_t*)page);
1059	  page->page_offset = start - (uint8_t*)page;
1060	  
1061	  // initialize page meta-data
1062	  page->reserved = (uint16_t)reserved;  
1063	  page->block_size = block_size;
1064	  page->memid = memid;
1065	  page->free_is_zero = memid.initially_zero;
1066	
1067	  mi_assert_internal((commit && commit_size==0) || (!commit && (commit_size <= UINT16_MAX * _mi_os_page_size())));
1068	  page->slice_pcommitted = (uint16_t)(commit_size / _mi_os_page_size());
1069	
1070	  page->heap = _mi_theap_heap(theap);
1071	  mi_page_set_theap(page,theap);
1072	  // mi_assert_internal(mi_page_theap(page) == _mi_heap_theap_peek(page->heap))
1073	
1074	  #if MI_PAGE_META_IS_ALIGNED
1075	  mi_atomic_store_ptr_release(mi_page_t,&page->self,page);
1076	  if (page_meta_is_separate) {
1077	    if (slice_count > 1) {
1078	      // at least two for large singleton blocks as guard pages can have a large offset beyond a single slice
1079	      for(size_t i = 1; i < max_page_meta_count; i++) {
1080	        mi_assert_internal(page[i].block_size == 0);
1081	        mi_atomic_store_ptr_release(mi_page_t,&page[i].self,page);
1082	      }
1083	    }
1084	  }
1085	  #if MI_DEBUG>1
1086	  mi_page_t* pstart = _mi_aligned_ptr_page0(slice_start);
1087	  mi_assert_internal(mi_atomic_load_ptr_acquire(mi_page_t,&pstart->self)==page);
1088	  if (reserved>1) {
1089	    mi_page_t* pend = _mi_aligned_ptr_page0(slice_start + (slice_count*MI_ARENA_SLICE_SIZE) - 1);
1090	    mi_assert_internal(mi_atomic_load_ptr_acquire(mi_page_t,&pend->self)==page);
1091	  }
1092	  #endif
1093	  #endif
1094	  
1095	  mi_assert_internal(page->free==NULL);
1096	  mi_assert_internal(page_meta_is_separate == mi_page_meta_is_separated(page));
1097	  mi_assert_internal(mi_page_slice_start(page) == slice_start);
1098	  mi_assert_internal(mi_page_size(page) <= page_noguard_size);
1099	  
1100	
1101	  // now register in the arena_pages
1102	  if (arena_pages!=NULL) {
1103	    mi_assert_internal(memid.memkind == MI_MEM_ARENA);
1104	    mi_bitmap_set(arena_pages->pages, memid.mem.arena.slice_index);
1105	  }
1106	
1107	  // and own it
1108	  mi_page_claim_ownership(page);
1109	
1110	  // register in the page map
1111	  if mi_unlikely(!_mi_page_map_register(page)) {
1112	    mi_arenas_page_free_prim(page);
1113	    return NULL;
1114	  }
1115	
1116	  // stats
1117	  mi_theap_stat_increase(theap, pages, 1);
1118	  mi_theap_stat_increase(theap, page_bins[_mi_page_stats_bin(page)], 1);
1119	
1120	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page),MI_PAGE_ALIGN));
1121	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1122	  mi_assert_internal(mi_page_block_size(page) == block_size);
1123	  // mi_assert_internal(mi_page_is_abandoned(page));
1124	  mi_assert_internal(mi_page_is_owned(page));
1125	
1126	  return page;
1127	}
1128	
1129	// Allocate a regular small/medium/large page.
1130	static mi_page_t* mi_arenas_page_regular_alloc(mi_theap_t* theap, size_t slice_count, size_t block_size)
1131	{
1132	  // 1. look for an abandoned page
1133	  mi_page_t* page = mi_arenas_page_try_find_abandoned(theap, slice_count, block_size);
1134	  if (page != NULL) {
1135	    return page;  // return as abandoned
1136	  }
1137	
1138	  // 2. find a free block, potentially allocating a new arena
1139	  const long commit_on_demand = mi_option_get(mi_option_page_commit_on_demand);
1140	  const bool commit = (mi_page_min_commit_size() >= slice_count * MI_ARENA_SLICE_SIZE ||           // always commit small pages
1141	                       (slice_count >= mi_slice_count_of_size(UINT16_MAX * _mi_os_page_size())) ||   // always commit pages too large to hold a 32-bit slice_committed
1142	                        (commit_on_demand == 2 && _mi_os_has_overcommit()) || (commit_on_demand == 0));
1143	  page = mi_arenas_page_alloc_fresh(theap, slice_count, block_size, 1, commit);
1144	  if (page == NULL) return NULL;
1145	
1146	  mi_assert_internal(page->memid.memkind != MI_MEM_ARENA || page->memid.mem.arena.slice_count == slice_count);
1147	  if (!_mi_page_init(theap, page)) {
1148	    _mi_arenas_page_free(page,theap);
1149	    return NULL;
1150	  }
1151	
1152	  return page;
1153	}
