1216	static void mi_arenas_page_free_prim(mi_page_t* page) {
1217	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1218	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1219	  mi_assert_internal(mi_page_is_owned(page));
1220	  mi_assert_internal(mi_page_all_free(page));
1221	  mi_assert_internal(page->next==NULL && page->prev==NULL);
1222	  
1223	  #if MI_DEBUG>1
1224	  if (page->memid.memkind==MI_MEM_ARENA && !mi_page_is_full(page)) {
1225	    size_t bin = _mi_bin(mi_page_block_size(page));
1226	    size_t slice_index;
1227	    size_t slice_count;
1228	    mi_arena_pages_t* arena_pages = NULL;
1229	    mi_arena_t* const arena = mi_page_arena_pages(page, &slice_index, &slice_count, &arena_pages);
1230	    mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
1231	    mi_assert_internal(mi_page_slice_committed(page) > 0 || mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
1232	    mi_assert_internal(bin >= MI_ARENA_BIN_COUNT || mi_bitmap_is_clearN(arena_pages->pages_abandoned[bin], slice_index, 1));
1233	    mi_assert_internal(mi_bitmap_is_setN(arena_pages->pages, slice_index, 1));
1234	    // note: we cannot check for `!mi_page_is_abandoned_and_mapped` since that may
1235	    // be (temporarily) not true if the free happens while trying to reclaim
1236	    // see `mi_arena_try_claim_abandoned`
1237	  }
1238	  #endif
1239	
1240	  // unregister page
1241	  _mi_page_map_unregister(page);
1242	
1243	  // recommit guard page at the end?
1244	  // we must do this since we may later allocate large spans over this page and cannot have a guard page in between
1245	  #if MI_SECURE >= 5
1246	  if (!page->memid.is_pinned) {
1247	    _mi_os_secure_guard_page_reset_before(mi_page_subproc(page), mi_page_slice_start(page) + mi_page_full_size(page), page->memid);
1248	  }
1249	  #endif
1250	
1251	  // and free
1252	  if (page->memid.memkind == MI_MEM_ARENA) {
1253	    mi_arena_pages_t* arena_pages;
1254	    size_t slice_index;
1255	    size_t slice_count; MI_UNUSED(slice_count);
1256	    mi_arena_t* const arena = mi_page_arena_pages(page, &slice_index, &slice_count, &arena_pages);
1257	    mi_assert_internal(arena_pages!=NULL);
1258	    mi_assert_internal(arena->subproc == mi_page_subproc(page));
1259	    mi_bitmap_clear(arena_pages->pages, slice_index);
1260	    const size_t slice_committed = mi_page_slice_committed(page);
1261	    if (slice_committed > 0) {
1262	      // if committed on-demand, set the commit bits to account commit properly
1263	      mi_assert_internal(mi_page_full_size(page) >= slice_committed);
1264	      const size_t total_slices = slice_committed / MI_ARENA_SLICE_SIZE;  // conservative
1265	      //mi_assert_internal(mi_bitmap_is_clearN(arena->slices_committed, slice_index, total_slices));
1266	      mi_assert_internal(slice_count >= total_slices);
1267	      if (total_slices > 0) {
1268	        mi_bitmap_setN(arena->slices_committed, slice_index, total_slices, NULL);
1269	      }
1270	      // any left over?
1271	      const size_t extra = slice_committed % MI_ARENA_SLICE_SIZE;
1272	      if (extra > 0) {
1273	        // pretend it was decommitted already
1274	        mi_subproc_stat_decrease(arena->subproc, committed, extra);
1275	      }
1276	    }
1277	    else {
1278	      mi_assert_internal(mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
1279	    }
1280	  }
1281	  if (mi_page_meta_is_separated(page)) { page->block_size = 0; }  // for assertion checking
1282	  _mi_arenas_free( mi_page_subproc(page), mi_page_slice_start(page), mi_page_full_size(page), page->memid);
1283	}
