1285	void _mi_arenas_page_free(mi_page_t* page, mi_theap_t* current_theapx) {
1286	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1287	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1288	  mi_assert_internal(mi_page_is_owned(page));
1289	  mi_assert_internal(mi_page_all_free(page));
1290	  mi_assert_internal(mi_page_is_abandoned(page));
1291	  mi_assert_internal(page->next==NULL && page->prev==NULL);
1292	  mi_assert_internal(mi_theap_matches_thread(current_theapx));
1293	
1294	  mi_heap_t* const heap = mi_page_heap(page);
1295	  mi_theapx_stat_decrease(heap, current_theapx, page_bins[_mi_page_stats_bin(page)], 1);
1296	  mi_theapx_stat_decrease(heap, current_theapx, pages, 1);
1297	  mi_arenas_page_free_prim(page);
1298	}
