1427	/* -----------------------------------------------------------
1428	  Arena free
1429	----------------------------------------------------------- */
1430	static void mi_arena_schedule_purge(mi_arena_t* arena, size_t slice_index, size_t slices);
1431	static void mi_arenas_try_purge(bool force, bool visit_all, mi_subproc_t* subproc, size_t tseq);
1432	
1433	void _mi_arenas_free(mi_subproc_t* subproc, void* p, size_t size, mi_memid_t memid) {
1434	  if (p==NULL) return;
1435	  if (size==0) return;
1436	
1437	  // need to set all memory to undefined as some parts may still be marked as no_access (like padding etc.)
1438	  mi_track_mem_undefined(p, size);
1439	
1440	  if (mi_memkind_is_os(memid.memkind)) {
1441	    // was a direct OS allocation, pass through
1442	    _mi_os_free(subproc, p, size, memid);
1443	  }
1444	  else if (memid.memkind == MI_MEM_ARENA) {
1445	    // allocated in an arena
1446	    size_t slice_count;
1447	    size_t slice_index;
1448	    mi_arena_t* arena = mi_arena_from_memid(memid, &slice_index, &slice_count);
1449	    mi_assert_internal(arena!=NULL);
1450	    mi_assert_internal(arena->subproc == subproc);
1451	    mi_assert_internal((size%MI_ARENA_SLICE_SIZE)==0);
1452	    mi_assert_internal((slice_count*MI_ARENA_SLICE_SIZE)==size);
1453	    mi_assert_internal(mi_arena_slice_start(arena,slice_index) <= (uint8_t*)p);
1454	    mi_assert_internal(mi_arena_slice_start(arena,slice_index) + mi_size_of_slices(slice_count) > (uint8_t*)p);
1455	    // checks
1456	    if (arena == NULL) {
1457	      _mi_error_message(EINVAL, "trying to free from an invalid arena: %p, size %zu, memkind: 0x%x\n", p, size, memid.memkind);
1458	      return;
1459	    }
1460	    mi_assert_internal(slice_index < arena->slice_count);
1461	    mi_assert_internal(slice_index >= mi_arena_info_slices(arena));
1462	    if (slice_index < mi_arena_info_slices(arena) || slice_index >= arena->slice_count) {
1463	      _mi_error_message(EINVAL, "trying to free from an invalid arena block: %p, size %zu, memkind: 0x%x\n", p, size, memid.memkind);
1464	      return;
1465	    }
1466	
1467	    // potentially decommit
1468	    if (!arena->memid.is_pinned /* && !arena->memid.initially_committed */) { // todo: allow decommit even if initially committed?
1469	      // (delay) purge the page
1470	      mi_arena_schedule_purge(arena, slice_index, slice_count);
1471	    }
1472	
1473	    // and make it available to others again
1474	    bool all_inuse = mi_bbitmap_setN(arena->slices_free, slice_index, slice_count);
1475	    if (!all_inuse) {
1476	      _mi_error_message(EAGAIN, "trying to free an already freed arena block: %p, size %zu\n", mi_arena_slice_start(arena,slice_index), mi_size_of_slices(slice_count));
1477	      return;
1478	    };
1479	  }
1480	  else if (memid.memkind == MI_MEM_MALLOC) {
1481	    _mi_free_subproc_safe(p);
1482	  }
1483	  else {
1484	    // arena was none, external, or static; nothing to do
1485	    mi_assert_internal(mi_memid_needs_no_free(memid));
1486	  }
1487	
1488	  // try to purge expired decommits
1489	  // mi_arenas_try_purge(false, false, NULL);
1490	}
