1537	  Remove an arena.
1538	----------------------------------------------------------- */
1539	
1540	// destroy owned arenas; this is unsafe and should only be done using `mi_option_destroy_on_exit`
1541	// for dynamic libraries that are unloaded and need to release all their allocated memory.
1542	static void mi_arenas_unsafe_destroy(mi_subproc_t* subproc) {
1543	  mi_assert_internal(subproc != NULL);
1544	  const size_t arena_count = mi_arenas_get_count(subproc);
1545	  for (size_t i = 0; i < arena_count; i++) {
1546	    mi_arena_t* arena = mi_atomic_load_ptr_acquire(mi_arena_t, &subproc->arenas[i]);
1547	    if (arena != NULL) {
1548	      // mi_lock_done(&arena->abandoned_visit_lock);
1549	      mi_atomic_store_ptr_release(mi_arena_t, &subproc->arenas[i], NULL);
1550	      if (mi_memkind_is_os(arena->memid.memkind)) {
1551	        _mi_os_free_ex(subproc, mi_arena_start(arena), mi_arena_size(arena), true, arena->memid);
1552	      }
1553	    }
1554	  }
1555	  // try to lower the max arena.
1556	  size_t expected = arena_count;
1557	  mi_atomic_cas_strong_acq_rel(&subproc->arena_count, &expected, (size_t)0);
