1666	  if (arena_pages==NULL) return NULL;
1667	  uint8_t* base = (uint8_t*)arena_pages + bitmap_base;
1668	  mi_assert_internal(_mi_is_aligned(base, MI_BCHUNK_SIZE));
1669	  arena_pages->pages = mi_arena_bitmap_init(slice_count, &base);
1670	  for (size_t i = 0; i < MI_ARENA_BIN_COUNT; i++) {
1671	    arena_pages->pages_abandoned[i] = mi_arena_bitmap_init(slice_count, &base);
