#define custom_realloc(p,s)   mi_heap_realloc(current_heap,p,s)
#define custom_free(p)        mi_free(p)
#else
#define custom_calloc(n,s)    mi_calloc(n,s)
#define custom_realloc(p,s)   mi_realloc(p,s)
#define custom_free(p)        mi_free(p)
#endif

